def get_common_equipment_price_for_slot(item_level, slot_key):
    """Розраховує ціну для звичайного предмета за слотом."""
    multiplier = COMMON_SHOP_PRICE_MULTIPLIERS.get(slot_key, 1.5)
    return round(max(1.0, item_level * multiplier), 2)

def confirm_common_equipment_shop_preview(user_id, item_id):
    """Canonical UI adapter for the atomic preview purchase path."""
    from .utils import format_gold
    preview = get_shop_preview_item(item_id, user_id)
    if not preview:
        return {"success": False, "message": "❌ Попередній перегляд предмета не знайдено або застарів."}
    price = float(preview[24] or 0)
    name = str(preview[1] or "Предмет")
    success, message = purchase_shop_preview_item(user_id, item_id)
    if not success:
        return {"success": False, "message": message}
    from .player import get_wallet
    return {
        "success": True,
        "message": (
            f"✅ Куплено базове спорядження.\n\n"
            f"📦 {name}\n"
            f"💳 Сплачено: {format_gold(price)}\n"
            f"💰 Залишилось: {format_gold(get_wallet(user_id))}"
        )
    }

def purchase_shop_preview_item(user_id, item_id):
    """Atomically revalidate, deliver, and charge for a shop-preview item."""
    # ROM 17.5.1 ATOMIC SHOP PURCHASE
    from .inventory import add_item

    try:
        cursor.execute("BEGIN IMMEDIATE")
        row = cursor.execute(
            """SELECT id, name, shop_preview_price
               FROM items
               WHERE id=? AND shop_preview_owner=?
                 AND shop_preview_price>0""",
            (item_id, user_id),
        ).fetchone()
        if not row:
            conn.rollback()
            return (False, "❌ Предмет не знайдено в магазині!")
        preview_item_id = int(row[0])
        current_item_id = promote_shop_preview_item(conn, preview_item_id)
        name = str(row[1] or "Предмет")
        price = float(row[2] or 0)
        wallet_row = cursor.execute(
            "SELECT COALESCE(gold,0) FROM users WHERE user_id=?", (user_id,)
        ).fetchone()
        wallet = float(wallet_row[0] or 0) if wallet_row else 0.0
        if wallet < price:
            conn.rollback()
            return (False, f"❌ Недостатньо золота! Потрібно: {price}, є: {wallet}")

        result = add_item(
            user_id, current_item_id, quantity=1, durability=100, commit=False
        )
        if (not result.get("success") or
                int(result.get("added", 0) or 0) != 1 or
                int(result.get("lost", 0) or 0) != 0):
            conn.rollback()
            return (False, result.get("message", "❌ Предмет не вдалося додати."))

        changed = cursor.execute(
            """UPDATE users SET gold=COALESCE(gold,0)-?
               WHERE user_id=? AND COALESCE(gold,0)>=?""",
            (price, user_id, price),
        ).rowcount
        if changed != 1:
            conn.rollback()
            return (False, "❌ Баланс змінився. Покупку скасовано.")
        cursor.execute("DELETE FROM items WHERE id=?", (preview_item_id,))
        conn.commit()
        return (True, f"✅ Куплено {name} за {price} золота!")
    except Exception as error:
        conn.rollback()
        return (False, f"❌ Не вдалося завершити покупку: {error}")

def recover_stranded_preview_item(conn,source_item_id):
    """Move an already-purchased item out of preview namespace atomically."""
    source_item_id=int(source_item_id)
    row=conn.execute("SELECT * FROM items WHERE id=? AND shop_preview_owner IS NULL AND COALESCE(shop_preview_price,0)=0",(source_item_id,)).fetchone()
    if not row: raise RuntimeError("Stranded preview item not found")
    columns=[str(r[1]) for r in conn.execute("PRAGMA table_info(items)")]
    target=allocate_generated_item_id(conn)
    values=list(row); values[columns.index("id")]=target
    conn.execute("INSERT INTO items("+",".join('"'+c+'"' for c in columns)+") VALUES("+",".join('?' for _ in columns)+")",values)
    reference_columns=(("auction_lots","item_ref_id"),("character_name_changes","item_id"),("crystal_shop_purchases","item_id"),("inventory","item_id"),("inventory_runes","rune_item_id"),("player_trade_offers","item_id"),("premium_item_grants","item_id"),("refine_attempts","item_id"))
    for table,column in reference_columns:
        known={str(r[1]) for r in conn.execute('PRAGMA table_info("'+table+'")')}
        if column in known: conn.execute(f'UPDATE "{table}" SET "{column}"=? WHERE "{column}"=?',(target,source_item_id))
    record_item_id_mapping(conn,source_item_id,target,"shop_preview_purchase_recovery","18.1.9b")
    conn.execute("DELETE FROM items WHERE id=?",(source_item_id,))
    return target
